45	    /**
46	     * Main entry point: find all eligible unpaid commissions, batch them,
47	     * and dispatch a per-payout job for each. Returns dispatch counts only —
48	     * actual results are reported per-job via Horizon.
49	     *
50	     * @return array{batches_dispatched: int, batches_created: int, batches_requeued: int}
51	     */
52	    public function processEligiblePayouts(): array
53	    {
54	        $stats = [
55	            'batches_dispatched' => 0,
56	            'batches_created' => 0,
57	            'batches_requeued' => 0,
58	        ];
59	
60	        // Re-dispatch any in-flight batches. ExecuteCommissionPayoutJob's idempotent
61	        // resume logic handles collecting/transferring states safely.
62	        // Skip wallet_currency_mismatch payouts — they cannot proceed until the brand
63	        // resolves the mismatch manually. Re-dispatching them floods Horizon with no
64	        // forward progress; the sweep picks them up again once an admin clears the code.
65	        $existingPending = CommissionPayout::query()
66	            ->whereIn('status', ['pending', 'pending_funds', 'collecting', 'transferring'])
67	            ->whereNull('processed_at')
68	            ->where('eligible_after', '<=', now())
69	            ->where(function ($q) {
70	                $q->whereNull('failure_code')
71	                    ->orWhere('failure_code', '!=', 'wallet_currency_mismatch');
72	            })
73	            ->orderBy('eligible_after')
74	            ->limit(500)
75	            ->get();
76	
77	        foreach ($existingPending as $pendingPayout) {
78	            ExecuteCommissionPayoutJob::dispatch($pendingPayout->id);
79	            $stats['batches_dispatched']++;
80	            $stats['batches_requeued']++;
81	        }
82	
83	        // Find all brands with unpaid approved orders, then apply per-brand hold days
84	        // to determine which orders have cleared their hold window.
85	        // Phase 3.5: source of truth moves from commission_movements to commerce.orders.
86	        $brandIds = Order::query()
87	            ->where('status', 'approved')
88	            ->whereNull('payout_id')
89	            ->where('refund_cents', 0)
90	            ->distinct()
91	            ->pluck('brand_professional_id');
92	
93	        // Pre-load brand store settings for hold-day lookups.
94	        $brandSettings = BrandStoreSettings::query()
95	            ->whereIn('professional_id', $brandIds)
96	            ->pluck('payout_hold_days', 'professional_id');
97	
98	        foreach ($brandIds as $brandId) {
99	            $holdDays = $this->resolveHoldDays($brandSettings[$brandId] ?? null);
100	            $cutoff = now()->utc()->subDays($holdDays);
101	
102	            $groups = Order::query()
103	                ->where('status', 'approved')
104	                ->whereNull('payout_id')
105	                ->where('refund_cents', 0)
106	                ->where('brand_professional_id', $brandId)
107	                ->where('occurred_at', '<=', $cutoff)
108	                ->select([
109	                    'brand_professional_id',
110	                    'affiliate_professional_id',
111	                    'currency_code',
112	                    DB::raw('SUM(commission_cents) as total_cents'),
113	                    DB::raw('COUNT(*) as entry_count'),
114	                ])
115	                ->groupBy('brand_professional_id', 'affiliate_professional_id', 'currency_code')
116	                ->having(DB::raw('SUM(commission_cents)'), '>', 0)
117	                ->get();
118	
119	            foreach ($groups as $group) {
120	                try {
121	                    $payout = $this->createPayoutBatch(
122	                        $group->brand_professional_id,
123	                        $group->affiliate_professional_id,
124	                        $group->currency_code,
125	                        $cutoff,
126	                    );
127	
128	                    if (! $payout) {
129	                        continue;
130	                    }
131	
132	                    $stats['batches_created']++;
133	                    ExecuteCommissionPayoutJob::dispatch($payout->id);
134	                    $stats['batches_dispatched']++;
135	                } catch (\Throwable $e) {
136	                    Log::error('Commission payout batch creation failed', [
137	                        'brand_id' => $group->brand_professional_id,
138	                        'affiliate_id' => $group->affiliate_professional_id,
139	                        'currency' => $group->currency_code,
140	                        'error' => $e instanceof ApiErrorException ? ($e->getStripeCode() ?? 'stripe_error') : get_class($e),
141	                    ]);
142	                }
143	            }
144	        }
145	
146	        return $stats;
147	    }
