149	    /**
150	     * Resolve the effective hold days for a brand.
151	     * Uses brand override if set, otherwise system default. Always >= system minimum.
152	     */
153	    private function resolveHoldDays(?int $brandPayoutHoldDays): int
154	    {
155	        $days = $brandPayoutHoldDays ?? $this->systemHoldDays;
156	
157	        return max($this->minHoldDays, $days);
158	    }
159	
160	    /**
161	     * Create a payout batch record and link all eligible orders.
162	     *
163	     * Phase 3.5+: reads from commerce.orders directly (not commission_movements).
164	     * Orders that are refunded after status='approved' have their status flipped to
165	     * 'partially_refunded'/'refunded', which the WHERE clause already excludes. Refunds
166	     * that arrive AFTER a payout is created are not reconciled in v1 — acceptable pre-beta;
167	     * tracked for Phase 4.
168	     */
169	    private function createPayoutBatch(
170	        string $brandId,
171	        string $affiliateId,
172	        string $currency,
173	        \DateTimeInterface $cutoff,
174	    ): ?CommissionPayout {
175	        // READ COMMITTED (PG default) — lockForUpdate() prevents a concurrent batch
176	        // from claiming the same orders between the SELECT and the payout_id stamp.
177	        return DB::transaction(function () use ($brandId, $affiliateId, $currency, $cutoff) {
178	            $orders = Order::query()
179	                ->where('status', 'approved')
180	                ->whereNull('payout_id')
181	                ->where('refund_cents', 0)
182	                ->where('brand_professional_id', $brandId)
183	                ->where('affiliate_professional_id', $affiliateId)
184	                ->where('currency_code', $currency)
185	                ->where('occurred_at', '<=', $cutoff)
186	                ->lockForUpdate()
187	                ->get();
188	
189	            if ($orders->isEmpty()) {
190	                return null;
191	            }
192	
193	            $grossCents = (int) $orders->sum('commission_cents');
194	            if ($grossCents <= 0) {
195	                return null;
196	            }
197	
198	            $platformFeeCents = (int) round($grossCents * $this->platformFeePercent / 100);
199	            $netPayoutCents = $grossCents - $platformFeeCents;
200	
201	            if ($netPayoutCents <= 0) {
202	                return null;
203	            }
204	
205	            // Per-payout grace window — 60d from creation. If the affiliate
206	            // hasn't activated Stripe Connect by then, VoidExpiredPayoutsJob
207	            // cancels this payout and clears the orders' payout_id stamps.
208	            // grace_period_days lives in config/sidest.php so ops can tune
209	            // the policy without a code release.
210	            // ledger_entry_count now counts orders included; column rename deferred to Phase 4.
211	            $payout = CommissionPayout::forceCreate([
212	                'brand_professional_id' => $brandId,
213	                'affiliate_professional_id' => $affiliateId,
214	                'status' => 'pending',
215	                'gross_commission_cents' => $grossCents,
216	                'platform_fee_cents' => $platformFeeCents,
217	                'net_payout_cents' => $netPayoutCents,
218	                'currency_code' => strtoupper($currency),
219	                'ledger_entry_count' => $orders->count(),
220	                'eligible_after' => $cutoff,
221	                'void_at' => now()->addDays($this->gracePeriodDays),
222	                'funding_source' => null,
223	            ]);
224	
225	            // Create one payout item per order; stamp orders.payout_id atomically
226	            // so the next sweep cannot double-claim these orders.
227	            foreach ($orders as $order) {
228	                CommissionPayoutItem::create([
229	                    'payout_id' => $payout->id,
230	                    'order_id' => $order->id,
231	                    'amount_cents' => $order->commission_cents,
232	                ]);
233	            }
234	
235	            Order::whereIn('id', $orders->pluck('id')->all())
236	                ->update(['payout_id' => $payout->id]);
237	
238	            return $payout;
239	        });
240	    }
