242	    /**
243	     * Process a single payout through the full 3-step flow with idempotent resume:
244	     *   1) Debit wallet balance (atomic with status update — crash-safe).
245	     *   2) Charge brand's card for any shortfall.
246	     *   3) Transfer net amount to affiliate via Stripe Connect.
247	     *
248	     * Each step checks the payout's current status before executing, so retries
249	     * (both Horizon automatic and admin manual) resume from where they left off
250	     * rather than restarting from scratch. This prevents double-debiting the wallet
251	     * and double-charging the brand's card.
252	     *
253	     * Return values:
254	     * - true:  completed
255	     * - null:  pending for funding/retry
256	     * - false: failed
257	     */
258	    public function processPayoutBatch(CommissionPayout $payout): ?bool
259	    {
260	        if ($payout->status === 'completed') {
261	            return true;
262	        }
263	
264	        $brand = Professional::find($payout->brand_professional_id);
265	        $affiliate = Professional::find($payout->affiliate_professional_id);
266	
267	        if (! $affiliate?->stripe_connect_account_id || $affiliate->stripe_connect_status !== 'active') {
268	            $this->markPendingFunding($payout, 'affiliate_not_connected', 'Affiliate Stripe Connect account is not active — holding for grace period');
269	
270	            return null;
271	        }
272	
273	        if (! $brand) {
274	            $this->failPayout($payout, 'brand_missing', 'Brand account was not found.');
275	
276	            return false;
277	        }
278	
279	        if (! $brand->stripe_customer_id || ! $brand->stripe_payment_method_id) {
280	            $this->markPendingFunding(
281	                $payout,
282	                'brand_payment_method_missing',
283	                'No payment method on file. Please add a card in your Stripe settings.',
284	            );
285	
286	            return null;
287	        }
288	
289	        $currencyUpper = strtoupper($payout->currency_code);
290	        $currencyLower = strtolower($currencyUpper);
291	        $amountToCollect = $payout->gross_commission_cents;
292	
293	        // Idempotency key suffix used only for PaymentIntents — retry_count is incremented
294	        // on each admin manual retry so a fresh PI is created rather than returning a
295	        // refunded/failed one from within the 24-hour idempotency TTL window.
296	        // Transfers intentionally use a stable key (no suffix) so Stripe returns the same
297	        // transfer on any retry, preventing a duplicate payout if the transfer succeeded
298	        // but the HTTP response was lost before the ID could be recorded.
299	        $retryKey = '_r'.$payout->retry_count;
300	
301	        // Step 1: Wallet debit — or resume from recorded state
302	        //
303	        // The debit and the status update are wrapped in a single DB::transaction
304	        // so a process crash between them can't leave the wallet reduced but the
305	        // payout record still showing 'pending' (which would cause a double-debit on retry).
306	        $walletDebitCents = 0;
307	        $chargeAmountCents = $amountToCollect;
308	
309	        if (in_array($payout->status, ['collecting', 'collected', 'transferring'], true)) {
310	            // Wallet debit already committed in a previous run — read from DB, don't re-debit.
311	            $walletDebitCents = (int) ($payout->wallet_debit_cents ?? 0);
312	            $chargeAmountCents = (int) ($payout->charge_cents ?? $amountToCollect);
313	        } else {
314	            // READ COMMITTED (PG default) — the payout status update and wallet debit
315	            // are atomic here; lockForUpdate() inside debitBrandManualBalancePartial
316	            // guards against concurrent debits on the wallet row itself.
317	            $hasCurrencyMismatch = false;
318	            DB::transaction(function () use ($payout, $brand, $amountToCollect, $currencyUpper, &$walletDebitCents, &$chargeAmountCents, &$hasCurrencyMismatch): void {
319	                $walletDebitCents = $this->debitBrandManualBalancePartial($brand->id, $amountToCollect, $currencyUpper, $hasCurrencyMismatch);
320	
321	                // Wallet has balance but in the wrong currency — abort without charging card.
322	                // markPendingFunding and notification happen outside the transaction below.
323	                if ($hasCurrencyMismatch) {
324	                    return;
325	                }
326	
327	                $chargeAmountCents = $amountToCollect - $walletDebitCents;
328	
329	                $fundingSource = 'card';
330	                if ($walletDebitCents > 0 && $chargeAmountCents > 0) {
331	                    $fundingSource = 'wallet_and_card';
332	                } elseif ($walletDebitCents > 0) {
333	                    $fundingSource = 'wallet';
334	                }
335	
336	                $payout->forceFill([
337	                    'status' => 'collecting',
338	                    'funding_source' => $fundingSource,
339	                    'wallet_debit_cents' => $walletDebitCents,
340	                    'charge_cents' => $chargeAmountCents,
341	                    'failure_code' => null,
342	                    'failure_reason' => null,
343	                ])->save();
344	            });
345	
346	            if ($hasCurrencyMismatch) {
347	                $walletCurrency = strtoupper((string) ($brand->stripe_manual_balance_currency ?? 'unknown'));
348	                $this->markPendingFunding(
349	                    $payout,
350	                    'wallet_currency_mismatch',
351	                    "Wallet balance is in {$walletCurrency} but payout requires {$currencyUpper}. Please contact support to resolve.",
352	                );
353	
354	                $this->publisher->publish(
355	                    professionalId: $payout->brand_professional_id,
356	                    frontendType: 'Warning',
357	                    category: 'commissions',
358	                    title: 'Commission payout on hold',
359	                    body: sprintf(
360	                        'A commission payout of %s could not be processed because your wallet balance is in %s. Please contact support to resolve the currency mismatch.',
361	                        $this->formatMoney($payout->gross_commission_cents, $payout->currency_code),
362	                        $walletCurrency,
363	                    ),
364	                    dedupeKey: "wallet_currency_mismatch.{$payout->id}",
365	                    ctaUrl: '/account/settings?section=wallet',
366	                );
367	
368	                return null;
369	            }
370	        }
371	
372	        // Step 2: Charge brand's card for the shortfall (if any)
373	        $latestChargeId = null;
374	
375	        if (in_array($payout->status, ['collected', 'transferring'], true)) {
376	            // PaymentIntent already succeeded in a previous run.
377	            // Retrieve the charge ID so we can use source_transaction on the transfer.
378	            if ($payout->stripe_payment_intent_id && $chargeAmountCents > 0) {
379	                $pi = $this->stripe->paymentIntents->retrieve($payout->stripe_payment_intent_id);
380	                $latestChargeId = $this->extractLatestChargeId($pi);
381	            }
382	        } elseif ($chargeAmountCents > 0) {
383	            try {
384	                $paymentIntent = $this->stripe->paymentIntents->create([
385	                    'amount' => $chargeAmountCents,
386	                    'currency' => $currencyLower,
387	                    'customer' => $brand->stripe_customer_id,
388	                    'payment_method' => $brand->stripe_payment_method_id,
389	                    'confirm' => true,
390	                    'off_session' => true,
391	                    'description' => "Commission payout #{$payout->id}",
392	                    'metadata' => [
393	                        'sidest_payout_id' => $payout->id,
394	                        'brand_id' => $brand->id,
395	                        'affiliate_id' => $affiliate->id,
396	                    ],
397	                ], ['idempotency_key' => 'pi_'.$payout->id.$retryKey]);
398	
399	                if ($paymentIntent->status !== 'succeeded') {
400	                    // SCA required — cancel the PI so the idempotency key is freed for the next
401	                    // attempt. Without cancellation the same key returns this stuck PI for 24h.
402	                    try {
403	                        $this->stripe->paymentIntents->cancel($paymentIntent->id);
404	                    } catch (\Throwable) {
405	                        // Non-critical: PI may already be in a terminal state
406	                    }
407	                    if ($walletDebitCents > 0) {
408	                        $this->creditBrandManualBalance($brand->id, $walletDebitCents, $currencyUpper);
409	                    }
410	                    $this->markPendingFunding($payout, 'charge_requires_action', 'Card charge requires authentication.');
411	
412	                    return null;
413	                }
414	
415	                $latestChargeId = $this->extractLatestChargeId($paymentIntent);
416	
417	                $payout->forceFill([
418	                    'stripe_payment_intent_id' => $paymentIntent->id,
419	                    'status' => 'collected',
420	                ])->save();
421	            } catch (ApiConnectionException|RateLimitException $e) {
422	                // Transient error — re-throw so Horizon retries with backoff.
423	                // Wallet debit is already committed in 'collecting' status; the
424	                // idempotent resume will skip re-debiting on the next attempt.
425	                throw $e;
426	            } catch (ApiErrorException $e) {
427	                // Terminal card failure (declined, invalid PM, SCA permanently blocked, etc.)
428	                if ($walletDebitCents > 0) {
429	                    $this->creditBrandManualBalance($brand->id, $walletDebitCents, $currencyUpper);
430	                }
431	                $this->markPendingFunding($payout, 'charge_failed', $e->getStripeCode() ?? 'stripe_error');
432	
433	                return null;
434	            }
435	        } else {
436	            // Fully funded by wallet — only advance status if not already past this step
437	            if (! in_array($payout->status, ['collected', 'transferring'], true)) {
438	                $payout->forceFill(['status' => 'collected'])->save();
439	            }
440	        }
441	
442	        // Step 3: Transfer net amount to the affiliate's Connect account
443	        try {
444	            if ($payout->status !== 'transferring') {
445	                $payout->forceFill(['status' => 'transferring'])->save();
446	            }
447	
448	            // Guard: skip transfer creation if a prior run already recorded the ID
449	            // (e.g. the transfer was saved but the server crashed before marking complete).
450	            if (! $payout->stripe_transfer_id) {
451	                $transferPayload = [
452	                    'amount' => $payout->net_payout_cents,
453	                    'currency' => $currencyLower,
454	                    'destination' => $affiliate->stripe_connect_account_id,
455	                    'description' => "Commission payout #{$payout->id} to {$affiliate->display_name}",
456	                    'metadata' => [
457	                        'sidest_payout_id' => $payout->id,
458	                        'brand_id' => $brand->id,
459	                        'affiliate_id' => $affiliate->id,
460	                    ],
461	                ];
462	
463	                if ($latestChargeId) {
464	                    $transferPayload['source_transaction'] = $latestChargeId;
465	                }
466	
467	                $transfer = $this->stripe->transfers->create(
468	                    $transferPayload,
469	                    // Stable key — no retry_count suffix. Stripe returns the same transfer
470	                    // on any retry (including admin retries that increment retry_count),
471	                    // preventing a duplicate payout when the transfer succeeded but the
472	                    // response was lost before stripe_transfer_id could be recorded.
473	                    ['idempotency_key' => 'tr_'.$payout->id]
474	                );
475	
476	                // Persist stripe_transfer_id before the completion record. If the process
477	                // crashes between these two saves, the guard above prevents re-creation.
478	                $payout->forceFill(['stripe_transfer_id' => $transfer->id])->save();
479	            }
480	
481	            $payout->forceFill([
482	                'status' => 'completed',
483	                'processed_at' => now(),
484	                'failure_code' => null,
485	                'failure_reason' => null,
486	            ])->save();
487	
488	            Log::info('Commission payout completed', [
489	                'payout_id' => $payout->id,
490	                'gross_cents' => $payout->gross_commission_cents,
491	                'wallet_debit_cents' => $walletDebitCents,
492	                'charge_cents' => $chargeAmountCents,
493	                'platform_fee_cents' => $payout->platform_fee_cents,
494	                'net_cents' => $payout->net_payout_cents,
495	                'funding_source' => $payout->funding_source,
496	                'currency' => $payout->currency_code,
497	            ]);
498	
499	            return true;
500	        } catch (ApiConnectionException|RateLimitException $e) {
501	            // Transient error — re-throw so Horizon retries from 'transferring' status.
502	            // Wallet and charge are NOT reversed. The stable transfer idempotency key
503	            // and the stripe_transfer_id guard above together ensure no duplicate transfer
504	            // is created if the original request succeeded but the response was lost.
505	            throw $e;
506	        } catch (ApiErrorException $e) {
507	            // Terminal transfer failure — credit wallet back, then attempt to auto-refund.
508	            if ($walletDebitCents > 0) {
509	                $this->creditBrandManualBalance($brand->id, $walletDebitCents, $currencyUpper);
510	            }
511	
512	            $failureCode = 'transfer_failed';
513	
514	            if ($payout->stripe_payment_intent_id && $chargeAmountCents > 0) {
515	                try {
516	                    $this->stripe->refunds->create([
517	                        'payment_intent' => $payout->stripe_payment_intent_id,
518	                    ], ['idempotency_key' => "rf_{$payout->id}_{$payout->stripe_payment_intent_id}"]);
519	                    $failureCode = 'transfer_failed_refunded';
520	                    // Clear PI ID so an admin retry can create a fresh PaymentIntent
521	                    // (same idempotency key within 24h would return the now-refunded PI).
522	                    $payout->forceFill(['stripe_payment_intent_id' => null])->save();
523	                } catch (\Throwable $refundEx) {
524	                    // Auto-refund failed — the brand may still be charged. Flag for manual resolution.
525	                    $failureCode = 'transfer_failed_refund_needed';
526	                    $payout->forceFill(['needs_manual_refund' => true])->save();
527	                    Log::error('Auto-refund after transfer failure failed — manual action required', [
528	                        'payout_id' => $payout->id,
529	                        'payment_intent_id' => $payout->stripe_payment_intent_id,
530	                        'transfer_error' => $e->getStripeCode() ?? 'stripe_error',
531	                        'refund_error' => $refundEx instanceof ApiErrorException ? ($refundEx->getStripeCode() ?? 'stripe_error') : get_class($refundEx),
532	                    ]);
533	                }
534	            }
535	
536	            $this->failPayout($payout, $failureCode, $e->getStripeCode() ?? 'stripe_error');
537	
538	            return false;
539	        }
540	    }
541	
542	    /**
543	     * Debit the brand's wallet balance, up to the requested amount (partial OK).
544	     * Returns the actual amount debited (0 if no balance available).
545	     *
546	     * Sets $hasCurrencyMismatch=true when the wallet has a positive balance but in a
547	     * different currency than $currencyCode — caller must treat this as a hard stop,
548	     * not a zero-balance case, to avoid silently charging the full amount to the card.
549	     */
550	    private function debitBrandManualBalancePartial(string $brandId, int $requestedCents, string $currencyCode, bool &$hasCurrencyMismatch = false): int
551	    {
552	        if ($requestedCents <= 0) {
553	            return 0;
554	        }
555	
556	        // READ COMMITTED (PG default) — lockForUpdate() on the professional row
557	        // serialises concurrent debits; no higher isolation level is required.
558	        return DB::transaction(function () use ($brandId, $requestedCents, $currencyCode, &$hasCurrencyMismatch) {
559	            $brand = Professional::query()
560	                ->whereKey($brandId)
561	                ->lockForUpdate()
562	                ->first();
563	
564	            if (! $brand) {
565	                return 0;
566	            }
567	
568	            $balance = max(0, (int) ($brand->stripe_manual_balance_cents ?? 0));
569	            $walletCurrency = strtoupper((string) ($brand->stripe_manual_balance_currency ?: $currencyCode));
570	
571	            if ($walletCurrency !== strtoupper($currencyCode)) {
572	                // Only flag as a mismatch when there's actual balance in the wrong currency.
573	                // An empty wallet with any currency is just "no funds" — not a mismatch.
574	                if ($balance > 0) {
575	                    $hasCurrencyMismatch = true;
576	                }
577	
578	                return 0;
579	            }
580	
581	            if ($balance <= 0) {
582	                return 0;
583	            }
584	
585	            $debit = min($balance, $requestedCents);
586	            $brand->stripe_manual_balance_cents = $balance - $debit;
587	            $brand->save();
588	
589	            return $debit;
590	        });
591	    }
592	
593	    public function creditBrandManualBalance(string $brandId, int $amountCents, string $currencyCode): void
594	    {
595	        if ($amountCents <= 0) {
596	            return;
597	        }
598	
599	        // READ COMMITTED (PG default) — lockForUpdate() serialises concurrent credits.
600	        DB::transaction(function () use ($brandId, $amountCents, $currencyCode) {
601	            $brand = Professional::query()
602	                ->whereKey($brandId)
603	                ->lockForUpdate()
604	                ->first();
605	
606	            if (! $brand) {
607	                return;
608	            }
609	
610	            $balance = (int) ($brand->stripe_manual_balance_cents ?? 0);
611	            $brand->stripe_manual_balance_cents = $balance + $amountCents;
612	            $brand->stripe_manual_balance_currency = strtoupper((string) ($brand->stripe_manual_balance_currency ?: $currencyCode));
613	            $brand->save();
614	        });
615	    }
