617	    private function extractLatestChargeId(object $paymentIntent): ?string
618	    {
619	        if (is_string($paymentIntent->latest_charge ?? null) && $paymentIntent->latest_charge !== '') {
620	            return $paymentIntent->latest_charge;
621	        }
622	
623	        if (is_object($paymentIntent->latest_charge ?? null) && is_string($paymentIntent->latest_charge->id ?? null)) {
624	            return $paymentIntent->latest_charge->id;
625	        }
626	
627	        if (is_object($paymentIntent->charges ?? null) && is_array($paymentIntent->charges->data ?? null)) {
628	            foreach ($paymentIntent->charges->data as $charge) {
629	                if (is_object($charge) && is_string($charge->id ?? null) && $charge->id !== '') {
630	                    return $charge->id;
631	                }
632	            }
633	        }
634	
635	        return null;
636	    }
