658	    private function failPayout(CommissionPayout $payout, string $code, string $reason): void
659	    {
660	        $payout->forceFill([
661	            'status' => 'failed',
662	            'failure_code' => $code,
663	            'failure_reason' => $reason,
664	        ])->save();
665	
666	        Log::warning('Commission payout failed', [
667	            'payout_id' => $payout->id,
668	            'code' => $code,
669	            'reason' => $reason,
670	        ]);
671	    }
