673	    /**
674	     * Manually retry a stuck payout batch (admin endpoint).
675	     *
676	     * Increments retry_count so a fresh Stripe idempotency key is used —
677	     * prevents Stripe returning a refunded/failed PI from within the 24h TTL window.
678	     *
679	     * Blocked for transfer_failed_refund_needed: the auto-refund itself failed, so
680	     * the brand may still be charged. Manual verification is required before retrying.
681	     *
682	     * Runs synchronously so the admin sees the result immediately.
683	     */
684	    public function retryPayout(CommissionPayout $payout): bool
685	    {
686	        if (! in_array($payout->status, ['failed', 'pending', 'pending_funds'], true)) {
687	            return false;
688	        }
689	
690	        // Auto-refund failed — manual verification required before retrying to avoid double-charging.
691	        if ($payout->failure_code === 'transfer_failed_refund_needed') {
692	            return false;
693	        }
694	
695	        // If the wallet was already debited in a previous run, resume from 'collecting'
696	        // so processPayoutBatch() enters its idempotent resume branch and skips
697	        // re-debiting. Resetting to 'pending' would bypass that branch and double-debit.
698	        $resumeStatus = ((int) ($payout->wallet_debit_cents ?? 0)) > 0 ? 'collecting' : 'pending';
699	
700	        $payout->forceFill([
701	            'status' => $resumeStatus,
702	            'failure_code' => null,
703	            'failure_reason' => null,
704	            'needs_manual_refund' => false,
705	            'retry_count' => ($payout->retry_count ?? 0) + 1,
706	        ])->save();
707	
708	        return $this->processPayoutBatch($payout) === true;
709	    }
