711	    private function formatMoney(int $cents, string $currencyCode): string
712	    {
713	        $prefix = match (strtoupper($currencyCode)) {
714	            'USD' => '$',
715	            'GBP' => '£',
716	            'EUR' => '€',
717	            'AUD' => 'A$',
718	            default => strtoupper($currencyCode).' ',
719	        };
720	
721	        return $prefix.number_format($cents / 100, 2, '.', ',');
722	    }
