789	
790	it('uses UTC for payout cutoff so an app-timezone offset does not shorten the hold window', function () {
791	    $conn = DB::connection('pgsql');
792	
793	    $conn->table('brand.brand_store_settings')->insert([
794	        'id' => 'bss-tz', 'professional_id' => 'brand-tz', 'payout_hold_days' => 7,
795	        'created_at' => now()->toDateTimeString(), 'updated_at' => now()->toDateTimeString(),
796	    ]);
797	
798	    // Carbon::now() converts testNow to date_default_timezone_get(), so we must set
799	    // the PHP default TZ BEFORE setting the mock. With Auckland (UTC+12) as the default,
800	    // now() returns '2026-05-02 12:00:00 +1200' and the two cutoff strings diverge:
801	    //   now()->subDays(7)        → '2026-04-25 12:00:00' (Auckland local, no TZ in string)
802	    //   now()->utc()->subDays(7) → '2026-04-25 00:00:00' (UTC)
803	    date_default_timezone_set('Pacific/Auckland');
804	    \Illuminate\Support\Carbon::setTestNow(\Illuminate\Support\Carbon::parse('2026-05-02 00:00:00', 'UTC'));
805	
806	    payoutSvc_seedBrand('brand-tz');
807	    payoutSvc_seedAffiliate('aff-tz');
808	
809	    // Order occurred 6 days + 18 hours ago (UTC) — still within the 7-day hold window.
