99	function payoutSvc_seedOrder(
100	    string $brandId,
101	    string $affiliateId,
102	    int $commissionCents = 1000,
103	    string $currency = 'AUD',
104	    ?\Illuminate\Support\Carbon $occurredAt = null,
105	    string $status = 'approved',
106	    int $refundCents = 0,
107	): string {
108	    $orderId = (string) Str::uuid();
109	    $ts = ($occurredAt ?? now())->toDateTimeString();
110	    DB::connection('pgsql')->table('commerce.orders')->insert([
111	        'id' => $orderId,
112	        'shopify_order_id' => 'shop_order_'.substr($orderId, 0, 8),
113	        'shopify_shop_domain' => 'test.myshopify.com',
114	        'shopify_updated_at' => $ts,
115	        'brand_professional_id' => $brandId,
116	        'affiliate_professional_id' => $affiliateId,
117	        'status' => $status,
118	        'gross_cents' => $commissionCents * 10,
119	        'discount_cents' => 0,
120	        'refund_cents' => $refundCents,
121	        'net_cents' => $commissionCents * 10 - $refundCents,
122	        'commission_cents' => $commissionCents,
